WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i+1 FROM n WHERE i < 59)
INSERT INTO boards(id, account_id, creator_id, name, created_at, updated_at) SELECT unhex(printf('02%030x', i)), unhex(printf('01%030x', 1 + i % 3)), unhex(printf('09%030x', 1)), 'B'||i, '2024-01-01 00:00:00', '2024-01-01 00:00:00' FROM n;
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i+2 FROM n WHERE i < 58)
INSERT INTO entropies(id, account_id, auto_postpone_period, container_id, container_type, created_at, updated_at)
